// Access gate for the hosted binders (Cloudflare Pages Functions). Lifted from the JPS gate
// (Dashboard-Creator hosting/functions/_middleware.js); only the brand lines differ. Every request under /<slug>/ needs that
// app's buyer access code once per device: the code is checked against its SHA-256 hash (in _apps.js,
// generated by build_sites.py), then kept in a long-lived HttpOnly cookie scoped to the app's path.
// The home-screen icons and manifest stay open so the phone can show the icon. The root goes to the website.
import APPS, { HOME } from './_apps.js';
const OPEN = /\/(manifest\.webmanifest|icons\/[\w-]+\.png)$/;
const norm = c => String(c || '').toUpperCase().replace(/[^0-9A-Z]/g, '').replace(/(.{4})(?=.)/g, '$1-');
const sha = async t => [...new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(t)))].map(b => b.toString(16).padStart(2, '0')).join('');
const cookieOf = (req, name) => (req.headers.get('cookie') || '').split(/;\s*/).map(p => p.split('=')).find(([k]) => k === name)?.[1];
const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

function page(app, slug, wrong) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(app.name)} · Open your app</title><meta name="robots" content="noindex"><meta name="theme-color" content="${app.tint}">
<link rel="manifest" href="/${slug}/manifest.webmanifest"><link rel="apple-touch-icon" href="/${slug}/icons/apple-touch-icon.png">
<style>:root{--t:${app.tint};--bg:#f6f3ec;--card:#fff;--ink:#1d1f1c;--ink2:#5d605a;--rule:#e6e1d6}
@media (prefers-color-scheme:dark){:root{--bg:#141614;--card:#1d201d;--ink:#eceae4;--ink2:#b3b2ab;--rule:#2c302c}}
*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:16px;background:var(--bg);color:var(--ink);font:16px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif}
main{width:100%;max-width:420px;padding:28px;border-radius:18px;background:var(--card);border:1px solid color-mix(in srgb,var(--t) 28%,var(--rule));box-shadow:0 10px 30px -14px rgba(0,0,0,.25)}
.ic{display:grid;place-items:center;width:52px;height:52px;border-radius:14px;background:var(--t);color:#fff;margin-bottom:16px}
.ic svg{width:28px;height:28px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
h1{font-size:22px;margin:0 0 6px}p{margin:0 0 18px;color:var(--ink2);font-size:15px}
input{width:100%;font:600 18px ui-monospace,Menlo,Consolas,monospace;letter-spacing:.08em;text-transform:uppercase;padding:13px 14px;border-radius:12px;border:1px solid var(--rule);background:transparent;color:inherit}
input:focus{outline:3px solid color-mix(in srgb,var(--t) 40%,transparent);border-color:var(--t)}
button{margin-top:12px;width:100%;font:700 16px system-ui,sans-serif;padding:13px;border:0;border-radius:12px;background:var(--t);color:#fff;cursor:pointer}
.err{color:#b3261e;font-size:14px;margin:10px 0 0}small{display:block;margin-top:16px;color:var(--ink2);font-size:13px}a{color:inherit}</style></head><body>
<main><div class="ic"><svg viewBox="0 0 24 24" aria-hidden="true">${app.icon}</svg></div><h1>${esc(app.name)}</h1>
<p>Enter the access code from your START_HERE page. You only need it once on each device.</p>
<form method="post"><label for="c" style="position:absolute;left:-9999px">Access code</label><input id="c" name="code" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="XXXX-XXXX-XXXX-XXXX" required autofocus>
${wrong ? '<p class="err" role="alert">That code doesn’t match this app. Check it in your download and try again.</p>' : ''}<button>Open the app</button></form>
<small>Your data stays on your device. Haven’t bought it yet? <a href="${esc(app.buy)}">Get ${esc(app.name)}</a> ${app.demo ? `or <a href="${esc(app.demo)}">try the free demo</a>` : ''}.</small></main></body></html>`;
}

export async function onRequest(ctx) {
  const url = new URL(ctx.request.url), slug = url.pathname.split('/')[1], app = APPS[slug];
  if (!slug) return HOME ? Response.redirect(HOME, 302) : new Response('Designs by Darowan', { status: 404 });
  if (!app) return ctx.next();
  if (url.pathname === '/' + slug) return Response.redirect(url.origin + '/' + slug + '/' + url.search, 301);
  if (OPEN.test(url.pathname)) return ctx.next();
  const name = 'dbd_' + slug.replace(/-/g, '_'), have = cookieOf(ctx.request, name);
  if (have && await sha(decodeURIComponent(have)) === app.hash) return ctx.next();
  const html = h => new Response(h, { status: 401, headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' } });
  if (ctx.request.method === 'POST') {
    let code = '';
    try { code = norm((await ctx.request.formData()).get('code')); } catch {}
    if (code && await sha(code) === app.hash) return new Response(null, { status: 303, headers: {
      location: '/' + slug + '/', 'cache-control': 'no-store',
      'set-cookie': `${name}=${encodeURIComponent(code)}; Path=/${slug}/; Max-Age=34560000; Secure; HttpOnly; SameSite=Lax` } });
    return html(page(app, slug, true));
  }
  return html(page(app, slug, false));
}
